<?php require '../includes/bootstrap.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO events(event_name,description,start_date,end_date,registration_deadline,status) VALUES(?,?,?,?,?,?)')->execute([trim($_POST['event_name']),trim($_POST['description']),$_POST['start_date'],$_POST['end_date'],$_POST['registration_deadline'],$_POST['status']]);flash('success','Event created.');redirect('events.php');}$rows=$pdo->query('SELECT * FROM events ORDER BY start_date DESC')->fetchAll();$title='Manage Events';$base='../';$nav='<a href="dashboard.php">Dashboard</a><a href="problems.php">Problems</a><a href="selections.php">Selections</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><h1>Manage Events</h1><div class="grid"><div class="card"><h3>Create event</h3><form method="post"><label>Name</label><input name="event_name" required><label>Description</label><textarea name="description"></textarea><label>Start</label><input type="date" name="start_date" required><label>End</label><input type="date" name="end_date" required><label>Registration deadline</label><input type="date" name="registration_deadline" required><label>Status</label><select name="status"><option>UPCOMING</option><option>OPEN</option><option>CLOSED</option><option>COMPLETED</option></select><div class="actions"><button class="btn">Create</button></div></form></div><div class="card" style="grid-column:span 2"><table class="table"><tr><th>Event</th><th>Dates</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['event_name'])?></td><td><?=e($r['start_date'])?> → <?=e($r['end_date'])?></td><td><span class="badge"><?=e($r['status'])?></span></td></tr><?php endforeach;?></table></div></div><?php include '../includes/footer.php';?>
